import{_ as o,o as d,c as s,a2 as t}from"./chunks/framework.Ck6QqhZl.js";const u=JSON.parse('{"title":"FAQ - Soundef","description":"","frontmatter":{},"headers":[],"relativePath":"docs/faq.md","filePath":"docs/faq.md"}'),a={name:"docs/faq.md"};function r(c,e,i,n,l,f){return d(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="faq-soundef" tabindex="-1">FAQ - Soundef <a class="header-anchor" href="#faq-soundef" aria-label="Permalink to &quot;FAQ - Soundef&quot;">​</a></h1><ul><li><strong>offset vs delay?</strong> <code>offset</code> is time from event trigger to layer start (ms, e.g. <code>metal offset 17ms</code>). We use <code>offset</code> to avoid confusion with a DSP delay line.</li><li><strong>Do I need a mixer?</strong> No pane - select a timeline lane → its <code>gain</code>/<code>pitch</code>/<code>offset</code>/<code>probability</code> appears in Controls as sliders/fields. <code>Mute</code>/<code>Solo</code> and a master bus are deferred; final gain is <code>sum layers + hard limiter -0.1dB</code> with a red clip dot.</li><li><strong>Bake clipped / red dot?</strong> Hard limiter at <code>-0.1dB</code> prevents file clipping, but we warn <code>bake-clipped</code> and show a persistent red clip dot on the final waveform + controls meter. Lower <code>gain</code> and re-bake.</li><li><strong>Absolute paths?</strong> <code>sources: [swords/body_01.wav]</code> is relative to <code>sounds/</code> (also <code>sounds/swords/...</code> alias is accepted). No <code>/absolute</code> or <code>../</code> escaping. The schema rejects <code>path-outside-sounds</code> and pack Export/Import checks paths.</li><li><strong>Why no auto-save?</strong> The spec editor is a VS Code-like buffer: preview runs from the buffer (instant, preserves comments), the file is only written on manual <code>Save</code> (<code>Cmd+S</code>, <code>● dirty</code>). External writes reload silently if clean, otherwise a banner shows <code>changed on disk - [Load] [Keep]</code>.</li><li><strong>Read vs write metadata?</strong> Forge reads audio tags on palette hover for search. It never writes into <code>sounds/*</code> files.</li><li><strong>Import/Export pack?</strong> Use <code>File → Export Pack</code> and <code>File → Import Pack</code> to share soundefs and sounds. The pack includes a manifest.</li></ul>',2)])])}const m=o(a,[["render",r]]);export{u as __pageData,m as default};
